  ('private.emit_event(uuid,text,text,text,uuid,integer,text,text,text,text,jsonb,timestamp with time zone)','67413effbbb3fa227397d355e0d4edfb'),
  ('private.set_updated_at()','d2ba7342ae061b491b5ec4bb74fb81c4')) pins(signature,body_md5) loop
  if (select md5(p.prosrc) from pg_proc p where p.oid=to_regprocedure(r.signature)) is distinct from r.body_md5
  then raise exception 'CANCEL_INFO_DEPENDENCY_CHANGED: %',r.signature using errcode='55000'; end if;
 end loop;
 if private.closure_source_digest_v5() is distinct from (select digest from ci_certificate)
  or private.closure_erasure_program_digest_v5() is distinct from (select program from ci_certificate)
 then raise exception 'CANCEL_INFO_CERTIFICATE_MOVED' using errcode='55000'; end if;
 if private.closure_source_digest_v5() is null or private.closure_erasure_program_digest_v5() is null
  or private.closure_source_digest_v5() is distinct from (select sha256 from private.closure_source_v5 where singleton)
  or private.closure_source_digest_v5() is distinct from (select sha256 from private.closure_erasure_source_v5 where singleton)
  or private.retention_ai_source_ready() is distinct from true
 then raise exception 'CANCEL_INFO_CERTIFICATE_NOT_READY_AFTER' using errcode='55000'; end if;
end
